function loadSamplePaperNav(){const t=document.querySelector(".sample-paper-nav");if(!t)return;const s=[{name:"Set 1",file:"set1/"},{name:"Set 2",file:"set2/"},{name:"Set 3",file:"set3/"},{name:"Set 4",file:"set4/"},{name:"Set 5",file:"set5/"},{name:"Set 6",file:"set6/"},{name:"Set 7",file:"set7/"}],a=window.location.pathname,i=a.includes("/set");let n=`
        <div class="sp-nav-inner">
            <span class="sp-nav-label">Quick Switch:</span>
            <div class="sp-nav-list">
    `;s.forEach(e=>{const l=e.file.split("/")[0],c=a.includes("/"+l+"/")?"active":"",o=i?"../"+e.file:e.file;n+=`<a href="${o}" class="sp-nav-link ${c}">${e.name}</a>`}),n+="</div></div>",t.innerHTML=n}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",loadSamplePaperNav):loadSamplePaperNav();
